namespace Trader.Core.Learning;

public sealed record TradingTerm(string English, string Portuguese, string Category, string DefinitionPt, string DefinitionEn);

public static class TradingTerms
{
    public const string Orders = "Ordens e execução";
    public const string Positions = "Posições e estilos";
    public const string Margin = "Margem e alavancagem";
    public const string Instruments = "Instrumentos";
    public const string Options = "Opções";
    public const string Technical = "Análise técnica";
    public const string Fundamentals = "Fundamentos e macro";
    public const string Risk = "Risco e desempenho";
    public const string Slang = "Gíria";

    public static IReadOnlyList<TradingTerm> Terms { get; } =
    [
        new("Market order", "Ordem a mercado", Orders, "Compra ou vende logo ao melhor preço disponível. Garante a execução, não o preço.", "Buys or sells immediately at the best available price. Guarantees execution, not the price."),
        new("Limit order", "Ordem limitada", Orders, "Só executa ao preço que definiste ou melhor. Garante o preço, não a execução.", "Only executes at your chosen price or better. Guarantees the price, not the execution."),
        new("Stop order / Stop-loss", "Ordem stop / Stop-loss", Orders, "Ordem que se ativa quando o preço atinge um nível, normalmente para limitar uma perda. Passa a ordem a mercado ao ser tocada, por isso o preço final pode ser pior.", "An order triggered when price reaches a level, usually to cap a loss. It becomes a market order once hit, so the fill price can be worse."),
        new("Stop-limit order", "Ordem stop-limite", Orders, "Um stop que, ao ser ativado, cria uma ordem limitada em vez de a mercado. Controla o preço, mas pode não executar.", "A stop that places a limit order when triggered instead of a market order. Controls the price, but may not fill."),
        new("Take profit (TP)", "Take profit (alvo de lucro)", Orders, "Ordem que fecha a posição quando o preço atinge o lucro desejado.", "An order that closes the position when price reaches the desired profit."),
        new("Trailing stop", "Stop dinâmico (trailing stop)", Orders, "Stop que acompanha o preço a uma distância fixa quando ele vai a teu favor, e não recua.", "A stop that follows price at a fixed distance when it moves in your favour, and never moves back."),
        new("OCO (one cancels the other)", "OCO (uma cancela a outra)", Orders, "Duas ordens ligadas, normalmente stop e alvo: quando uma executa, a outra é cancelada.", "Two linked orders, usually stop and target: when one fills, the other is cancelled."),
        new("Good till cancelled (GTC)", "Válida até cancelamento", Orders, "Ordem que fica ativa até a executares ou cancelares (algumas corretoras impõem um limite de dias).", "An order that stays active until filled or cancelled (some brokers cap the number of days)."),
        new("Day order", "Ordem do dia", Orders, "Ordem que expira no fim da sessão se não for executada.", "An order that expires at the end of the session if not filled."),
        new("Fill", "Execução (preenchimento)", Orders, "O momento em que a ordem é executada no mercado. Pode ser total ou parcial.", "The moment an order is executed in the market. It can be full or partial."),
        new("Slippage", "Derrapagem (slippage)", Orders, "Diferença entre o preço esperado e o preço em que a ordem foi realmente executada. Aumenta em mercados rápidos ou pouco líquidos.", "The difference between the expected price and the price actually filled. It grows in fast or illiquid markets."),
        new("Bid", "Preço de compra (bid)", Orders, "O preço mais alto que alguém está disposto a pagar agora. É o preço a que vendes a mercado.", "The highest price someone is willing to pay now. It is the price at which you sell at market."),
        new("Ask (offer)", "Preço de venda (ask)", Orders, "O preço mais baixo a que alguém vende agora. É o preço a que compras a mercado.", "The lowest price at which someone sells now. It is the price at which you buy at market."),
        new("Spread", "Spread (diferencial)", Orders, "Diferença entre ask e bid. É um custo implícito de cada operação.", "The difference between ask and bid. It is an implicit cost of every trade."),
        new("Liquidity", "Liquidez", Orders, "Facilidade de comprar ou vender sem mexer no preço. Muito volume e spread curto indicam boa liquidez.", "How easily you can buy or sell without moving the price. High volume and a tight spread mean good liquidity."),
        new("Volume", "Volume", Orders, "Quantidade de unidades negociadas num período. Confirma a força de um movimento.", "Number of units traded in a period. It confirms the strength of a move."),
        new("Gap", "Gap (salto de preço)", Orders, "Espaço sem negociação entre o fecho de uma sessão e a abertura seguinte, normalmente por notícias. Pode ultrapassar o stop sem o executar ao preço definido.", "A space with no trading between one session's close and the next open, usually due to news. It can jump over your stop and fill it at a worse price."),
        new("Pre-market / After-hours", "Pré-mercado / Pós-mercado", Orders, "Negociação antes da abertura e depois do fecho oficial, com menos liquidez e spreads maiores.", "Trading before the open and after the official close, with lower liquidity and wider spreads."),

        new("Long (buy)", "Posição longa (compra)", Positions, "Comprar a esperar que o preço suba. Ganhas se subir, perdes se descer.", "Buying in the expectation that price will rise. You profit if it goes up and lose if it goes down."),
        new("Short (sell short)", "Posição curta (venda a descoberto)", Positions, "Vender algo que não tens (emprestado ou via CFD) a esperar que desça, para recomprar mais barato. A perda teórica é ilimitada.", "Selling something you don't own (borrowed or via CFD) expecting it to fall, to buy it back cheaper. The theoretical loss is unlimited."),
        new("Buy to open / Sell to close", "Comprar para abrir / Vender para fechar", Positions, "Abrir uma posição longa e fechá-la. O inverso numa venda a descoberto é 'sell to open' e 'buy to cover'.", "Opening a long position and closing it. In a short sale the reverse is 'sell to open' and 'buy to cover'."),
        new("Cover (buy to cover)", "Cobrir (comprar para cobrir)", Positions, "Comprar de volta para fechar uma posição curta.", "Buying back to close a short position."),
        new("Entry / Exit", "Entrada / Saída", Positions, "O preço e o momento em que abres e em que fechas uma posição.", "The price and moment at which you open and close a position."),
        new("Position size", "Tamanho da posição", Positions, "Quanto compras ou vendes. Deve resultar do risco que aceitas e da distância ao stop.", "How much you buy or sell. It should follow from the risk you accept and the distance to the stop."),
        new("Lot", "Lote", Positions, "Unidade-padrão de negociação, sobretudo em forex (1 lote padrão = 100 000 unidades da moeda base).", "Standard trading unit, mostly in forex (1 standard lot = 100,000 units of the base currency)."),
        new("Pip", "Pip", Positions, "Menor variação habitual de um par de moedas, normalmente 0,0001 (0,01 nos pares com iene).", "The usual smallest move of a currency pair, normally 0.0001 (0.01 for yen pairs)."),
        new("Tick", "Tick", Positions, "A menor variação de preço permitida num instrumento.", "The smallest price move allowed for an instrument."),
        new("Hedge", "Cobertura (hedge)", Positions, "Posição aberta para reduzir o risco de outra, por exemplo comprar uma put para proteger ações.", "A position opened to reduce the risk of another, for example buying a put to protect shares."),
        new("Scalping", "Scalping", Positions, "Dezenas de operações muito curtas, de segundos a minutos, para ganhos pequenos. Os custos pesam muito.", "Dozens of very short trades, from seconds to minutes, for small gains. Costs weigh heavily."),
        new("Day trading", "Negociação intradiária (day trading)", Positions, "Abrir e fechar posições no mesmo dia, sem ficar com risco overnight.", "Opening and closing positions on the same day, with no overnight risk."),
        new("Swing trading", "Swing trading", Positions, "Manter posições de alguns dias a semanas, para apanhar um movimento intermédio.", "Holding positions for a few days to weeks to catch an intermediate move."),
        new("Position trading", "Negociação de longo prazo", Positions, "Manter meses ou anos, guiado por tendências e fundamentos.", "Holding for months or years, driven by trends and fundamentals."),
        new("Bull market / Bullish", "Mercado de alta (touro) / Otimista", Positions, "Fase de preços a subir de forma sustentada; 'bullish' é ter a expectativa de subida.", "A phase of sustained rising prices; 'bullish' means expecting a rise."),
        new("Bear market / Bearish", "Mercado de baixa (urso) / Pessimista", Positions, "Fase de queda sustentada (tipicamente −20% ou mais); 'bearish' é esperar descida.", "A phase of sustained decline (typically −20% or more); 'bearish' means expecting a fall."),
        new("Sideways market (range)", "Mercado lateral", Positions, "Preço a oscilar entre um mínimo e um máximo sem tendência clara.", "Price oscillating between a low and a high with no clear trend."),
        new("Rally", "Subida forte (rally)", Positions, "Subida rápida e prolongada do preço.", "A fast, sustained rise in price."),
        new("Correction", "Correção", Positions, "Descida de 10% ou mais face ao máximo recente, sem ser uma tendência de baixa.", "A decline of 10% or more from a recent high that is not a bear trend."),
        new("Crash", "Colapso (crash)", Positions, "Queda muito rápida e forte, normalmente com pânico.", "A very fast, steep fall, usually with panic."),

        new("Margin", "Margem", Margin, "Dinheiro que a corretora te exige como garantia para manteres uma posição alavancada.", "Money your broker requires as collateral to hold a leveraged position."),
        new("Leverage", "Alavancagem", Margin, "Usar margem para abrir uma posição maior do que o capital. Com 5× uma variação de 1% vale 5% da margem, para ganhos e perdas.", "Using margin to open a position larger than your capital. At 5× a 1% move is worth 5% of the margin, for gains and losses."),
        new("Margin call", "Chamada de margem (margin call)", Margin, "Aviso da corretora de que o capital caiu abaixo do nível exigido: tens de depositar mais dinheiro ou reduzir posições, senão fecham-nas por ti.", "A broker warning that your equity fell below the required level: you must deposit more money or reduce positions, or they will close them for you."),
        new("Stop out (liquidation)", "Fecho forçado (stop out / liquidação)", Margin, "A corretora fecha posições automaticamente quando a margem é insuficiente, muitas vezes com perdas realizadas e sem aviso.", "The broker automatically closes positions when margin is insufficient, often locking in losses without warning."),
        new("Used margin / Free margin", "Margem usada / Margem livre", Margin, "A margem usada está presa nas posições abertas; a livre é o que resta para novas posições e para aguentar perdas.", "Used margin is locked in open positions; free margin is what remains for new positions and to absorb losses."),
        new("Maintenance margin", "Margem de manutenção", Margin, "Mínimo de capital que tens de manter para não sofreres margin call.", "The minimum equity you must keep to avoid a margin call."),
