        new("Stock split", "Desdobramento de ações (split)", Instruments, "A empresa multiplica o número de ações e reduz o preço de cada uma na mesma proporção, sem alterar o valor total.", "The company multiplies the number of shares and cuts each price in the same proportion, leaving total value unchanged."),
        new("IPO (initial public offering)", "Oferta pública inicial (IPO)", Instruments, "A primeira venda de ações de uma empresa ao público, que passa a estar cotada.", "A company's first sale of shares to the public, after which it is listed."),
        new("Market capitalisation", "Capitalização bolsista", Instruments, "Valor total das ações de uma empresa: preço × número de ações.", "Total value of a company's shares: price × number of shares."),
