        new("Expiration date", "Data de vencimento (expiração)", Options, "Último dia em que a opção pode ser exercida. Depois disso vale zero se estiver fora de dinheiro.", "The last day the option can be exercised. After that it is worthless if out of the money."),
        new("In / At / Out of the money (ITM, ATM, OTM)", "Dentro / No / Fora de dinheiro (ITM, ATM, OTM)", Options, "Uma call está dentro de dinheiro quando o preço está acima do strike; no dinheiro quando é igual; fora quando está abaixo. Nas puts é ao contrário.", "A call is in the money when price is above the strike, at the money when equal and out of the money when below. For puts it is the opposite."),
        new("Intrinsic value / Time value", "Valor intrínseco / Valor temporal", Options, "O intrínseco é o ganho se exercesses agora; o temporal é o resto do prémio, que se esgota até ao vencimento.", "Intrinsic value is the gain if exercised now; time value is the rest of the premium, which decays until expiry."),
        new("Exercise", "Exercício", Options, "Usar o direito da opção: o comprador de uma call compra as ações ao strike.", "Using the option's right: the call buyer buys the shares at the strike."),
        new("Assignment", "Atribuição", Options, "Quando o vendedor de uma opção é obrigado a cumprir o contrato porque o comprador a exerceu.", "When the seller of an option is obliged to honour the contract because the buyer exercised it."),
        new("Writing (selling) options", "Vender opções (writing)", Options, "Receber o prémio em troca de assumir a obrigação. O risco pode ser grande, ou ilimitado numa call a descoberto.", "Receiving the premium in exchange for taking on the obligation. The risk can be large, or unlimited on a naked call."),
        new("Covered call", "Call coberta", Options, "Vender uma call sobre ações que já tens, para receber prémio. Limita o ganho acima do strike.", "Selling a call on shares you already own to collect premium. It caps the gain above the strike."),
