        new("MACD", "MACD", Technical, "Indicador de momentum baseado na diferença entre duas médias exponenciais. Os cruzamentos sinalizam mudanças de força.", "A momentum indicator based on the difference between two exponential averages. Crossovers signal changes in strength."),
        new("Bollinger Bands", "Bandas de Bollinger", Technical, "Envelope de 2 desvios-padrão em torno de uma média móvel, que alarga com a volatilidade.", "An envelope of 2 standard deviations around a moving average, widening with volatility."),
        new("ATR (average true range)", "ATR (amplitude média verdadeira)", Technical, "Mede a volatilidade como a amplitude média das velas. Muito usado para definir stops.", "Measures volatility as the average candle range. Widely used to set stops."),
        new("ADX", "ADX", Technical, "Mede a força da tendência (não a direção). Abaixo de ~20 o mercado costuma estar lateral.", "Measures trend strength (not direction). Below ~20 the market is usually sideways."),
        new("VWAP", "VWAP (preço médio ponderado pelo volume)", Technical, "Preço médio da sessão ponderado pelo volume. Referência intradiária para compradores e vendedores.", "The session's volume-weighted average price. An intraday reference for buyers and sellers."),
        new("Fibonacci retracement", "Retração de Fibonacci", Technical, "Níveis (38,2%, 50%, 61,8%) usados para estimar até onde um recuo pode ir antes de a tendência continuar.", "Levels (38.2%, 50%, 61.8%) used to estimate how far a pullback may go before the trend resumes."),
        new("Candlestick", "Vela japonesa", Technical, "Mostra abertura, máximo, mínimo e fecho de um período. Corpo e pavios (sombras) descrevem a disputa entre compradores e vendedores.", "Shows a period's open, high, low and close. The body and wicks (shadows) describe the fight between buyers and sellers."),
        new("Divergence", "Divergência", Technical, "O preço e um indicador (como o RSI) caminham em sentidos opostos, avisando de perda de força.", "Price and an indicator (such as RSI) move in opposite directions, warning of weakening strength."),
        new("Overbought / Oversold", "Sobrecomprado / Sobrevendido", Technical, "Subiu ou desceu depressa demais e pode corrigir. Em tendências fortes pode manter-se assim muito tempo.", "It rose or fell too fast and may correct. In strong trends it can stay that way for a long time."),

        new("Earnings", "Resultados (earnings)", Fundamentals, "Relatório trimestral de lucros de uma empresa. Costuma causar saltos de preço.", "A company's quarterly profit report. It often causes price jumps."),
        new("EPS (earnings per share)", "Lucro por ação (EPS)", Fundamentals, "Lucro da empresa dividido pelo número de ações.", "Company profit divided by the number of shares."),
        new("P/E ratio", "Rácio preço/lucro (PER)", Fundamentals, "Preço da ação a dividir pelo lucro por ação. Mostra quantos anos de lucro estás a pagar.", "Share price divided by earnings per share. It shows how many years of earnings you are paying for."),
        new("Guidance", "Previsões da gestão (guidance)", Fundamentals, "Expectativas que a empresa dá para resultados futuros. Muitas vezes mexe mais no preço do que os números passados.", "Expectations a company gives for future results. It often moves price more than past numbers."),
        new("Interest rate", "Taxa de juro", Fundamentals, "Custo do dinheiro fixado pelo banco central. Taxas mais altas tendem a pressionar ações e favorecer a moeda.", "The cost of money set by the central bank. Higher rates tend to pressure stocks and support the currency."),
        new("Central bank (Fed, ECB)", "Banco central (Fed, BCE)", Fundamentals, "Define a política monetária. As reuniões (FOMC na Fed) são eventos de grande volatilidade.", "Sets monetary policy. Meetings (FOMC at the Fed) are highly volatile events."),
        new("Inflation (CPI)", "Inflação (IPC)", Fundamentals, "Subida geral dos preços. Dados acima do esperado antecipam juros mais altos.", "A general rise in prices. Readings above expectations anticipate higher rates."),
        new("Non-farm payrolls (NFP)", "Emprego não agrícola (NFP)", Fundamentals, "Relatório mensal dos EUA sobre criação de emprego, um dos que mais mexe nos mercados.", "A monthly US jobs report, one of the biggest market movers."),
        new("Sentiment", "Sentimento", Fundamentals, "Humor dominante dos investidores. Extremos de otimismo ou pânico servem de contexto, não de sinal isolado.", "The prevailing mood of investors. Extremes of optimism or panic serve as context, not as a lone signal."),
        new("Volatility index (VIX)", "Índice de volatilidade (VIX)", Fundamentals, "Mede a volatilidade esperada do S&P 500. É o 'índice do medo': sobe quando o mercado cai depressa.", "Measures the expected volatility of the S&P 500. It is the 'fear index': it rises when the market falls fast."),

        new("Risk/reward ratio (R:R)", "Rácio risco/retorno (R:R)", Risk, "Ganho potencial no alvo a dividir pela perda potencial no stop.", "Potential gain at the target divided by potential loss at the stop."),
        new("R-multiple", "Múltiplo de R", Risk, "Resultado medido em unidades de risco: perder o stop é −1R, ganhar o dobro do risco é +2R.", "Result measured in units of risk: hitting the stop is −1R, gaining twice the risk is +2R."),
        new("Win rate", "Taxa de acerto", Risk, "Percentagem de trades ganhadoras. Sozinha diz pouco: depende do risco/retorno.", "Percentage of winning trades. Alone it says little: it depends on the risk/reward."),
